import {
  githubAppTokenBrokerAudience,
  githubAppTokenBrokerEndpoint,
  createGitHubAppTokenClientBindings,
  requestGitHubAppInstallationToken,
  type GitHubAppTokenClientBindings,
} from "@cyspbot/cyspbot/github-app-token";
import { describe, expect, it } from "vitest";

type GeneratedCyspbotEnvWithWorkloadIdentityRpc = Omit<CyspbotEnv, "WORKLOAD_IDENTITY_ISSUER"> & {
  WORKLOAD_IDENTITY_ISSUER: CyspbotEnv["WORKLOAD_IDENTITY_ISSUER"] & {
    issueToken(audience: string): Promise<{ token: string }>;
  };
};

describe("requestGitHubAppInstallationToken", () => {
  it("adapts a generated service binding to the CWI RPC contract", async () => {
    const audiences: string[] = [];
    const generatedEnv = {
      GITHUB_APP_TOKEN_BROKER: createGeneratedServiceBinding(),
      WORKLOAD_IDENTITY_ISSUER: {
        ...createGeneratedServiceBinding(),
        issueToken(audience: string) {
          audiences.push(audience);
          return Promise.resolve({ token: "eyJ.test.workload.identity" });
        },
      },
    } satisfies GeneratedCyspbotEnvWithWorkloadIdentityRpc;

    const bindings = createGitHubAppTokenClientBindings(generatedEnv);
    const response = await requestGitHubAppInstallationToken(bindings, {
      resource: "https://api.github.com/repos/chikachow/cyspbot",
      scope: "contents:read",
    });

    expect(response.status).toBe(501);
    expect(audiences).toEqual([githubAppTokenBrokerAudience]);
  });

  it("rejects a generated service binding without the CWI RPC method", () => {
    const generatedEnv = {
      GITHUB_APP_TOKEN_BROKER: createGeneratedServiceBinding(),
      WORKLOAD_IDENTITY_ISSUER: createGeneratedServiceBinding(),
    } satisfies CyspbotEnv;

    expect(() => createGitHubAppTokenClientBindings(generatedEnv)).toThrow(
      "WORKLOAD_IDENTITY_ISSUER must expose issueToken()",
    );
  });

  it("gets a workload identity token and sends an OAuth token exchange", async () => {
    const audiences: string[] = [];
    const requests: Array<{ input: RequestInfo | URL; init: RequestInit | undefined }> = [];
    const brokerResponse = new Response(
      JSON.stringify({
        access_token: "ghs_test_token",
        expires_in: 300,
        issued_token_type: "urn:ietf:params:oauth:token-type:access_token",
        scope: "contents:read",
        token_type: "Bearer",
      }),
      { headers: { "content-type": "application/json" }, status: 200 },
    );
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch(input, init) {
          requests.push({ init, input });
          return Promise.resolve(brokerResponse);
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken(audience: string) {
          audiences.push(audience);
          return Promise.resolve({ token: "eyJ.test.workload.identity" });
        },
      },
    };

    const response = await requestGitHubAppInstallationToken(env, {
      resource: "https://api.github.com/repos/chikachow/cyspbot",
      scope: "contents:read",
    });

    expect(response).toBe(brokerResponse);
    expect(audiences).toEqual([githubAppTokenBrokerAudience]);
    expect(requests).toHaveLength(1);
    expect(requests[0]?.input).toBe(githubAppTokenBrokerEndpoint);
    expect(requests[0]?.init?.method).toBe("POST");
    expect(new Headers(requests[0]?.init?.headers).get("accept")).toBe("application/json");
    expect(new Headers(requests[0]?.init?.headers).get("content-type")).toBe(
      "application/x-www-form-urlencoded",
    );

    const requestBody = requests[0]?.init?.body;
    if (!(requestBody instanceof URLSearchParams)) {
      throw new TypeError("expected a URLSearchParams token-exchange body");
    }

    expect(Object.fromEntries(requestBody)).toEqual({
      grant_type: "urn:ietf:params:oauth:grant-type:token-exchange",
      requested_token_type: "urn:ietf:params:oauth:token-type:access_token",
      resource: "https://api.github.com/repos/chikachow/cyspbot",
      scope: "contents:read",
      subject_token: "eyJ.test.workload.identity",
      subject_token_type: "urn:ietf:params:oauth:token-type:id_token",
    });
  });

  it("does not contact the broker when the request is empty", async () => {
    let issuerCalls = 0;
    let brokerCalls = 0;
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch() {
          brokerCalls += 1;
          return Promise.reject(new Error("broker should not be contacted"));
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken() {
          issuerCalls += 1;
          return Promise.resolve({ token: "unused" });
        },
      },
    };

    await expect(
      requestGitHubAppInstallationToken(env, {
        resource: "",
        scope: "contents:read",
      }),
    ).rejects.toThrow("resource must be a non-empty string");
    expect(issuerCalls).toBe(0);
    expect(brokerCalls).toBe(0);
  });

  it("does not contact the broker when the issuer returns no token", async () => {
    let brokerCalls = 0;
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch() {
          brokerCalls += 1;
          return Promise.reject(new Error("broker should not be contacted"));
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken: async () => ({ token: "" }),
      },
    };

    await expect(
      requestGitHubAppInstallationToken(env, {
        resource: "https://api.github.com/repos/chikachow/cyspbot",
        scope: "contents:read",
      }),
    ).rejects.toThrow("WORKLOAD_IDENTITY_ISSUER returned an invalid token");
    expect(brokerCalls).toBe(0);
  });

  it("requires a non-empty scope before contacting either binding", async () => {
    let issuerCalls = 0;
    let brokerCalls = 0;
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch() {
          brokerCalls += 1;
          return Promise.reject(new Error("broker should not be contacted"));
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken() {
          issuerCalls += 1;
          return Promise.resolve({ token: "unused" });
        },
      },
    };

    await expect(
      requestGitHubAppInstallationToken(env, {
        resource: "https://api.github.com/repos/chikachow/cyspbot",
        scope: " ",
      }),
    ).rejects.toThrow("scope must be a non-empty string");
    expect(issuerCalls).toBe(0);
    expect(brokerCalls).toBe(0);
  });

  it("returns broker errors unchanged for the caller to interpret", async () => {
    const brokerResponse = new Response(JSON.stringify({ error: "invalid_scope" }), {
      headers: { "content-type": "application/json" },
      status: 400,
    });
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch() {
          return Promise.resolve(brokerResponse);
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken: async () => ({ token: "eyJ.test.workload.identity" }),
      },
    };

    const response = await requestGitHubAppInstallationToken(env, {
      resource: "https://api.github.com/repos/chikachow/cyspbot",
      scope: "contents:read",
    });

    expect(response).toBe(brokerResponse);
    expect(response.status).toBe(400);
    await expect(response.json()).resolves.toEqual({ error: "invalid_scope" });
  });
});

function createGeneratedServiceBinding() {
  return {
    connect() {
      throw new Error("service binding connect() is not used by this test");
    },
    fetch() {
      return Promise.resolve(new Response(null, { status: 501 }));
    },
  };
}
