const tokenExchangeGrantType = "urn:ietf:params:oauth:grant-type:token-exchange";
const accessTokenType = "urn:ietf:params:oauth:token-type:access_token";
const oidcIdTokenType = "urn:ietf:params:oauth:token-type:id_token";

/** The logical audience shared by the workload issuer and token broker. */
export const githubAppTokenBrokerAudience = "https://cyspbot.chikachow.org";

/** The broker's OAuth 2.0 Token Exchange endpoint. */
export const githubAppTokenBrokerEndpoint = "https://cyspbot.chikachow.org/token";

export interface GitHubAppInstallationTokenRequest {
  readonly resource: string;
  readonly scope: string;
}

interface WorkloadIdentityToken {
  readonly token: string;
}

interface WorkloadIdentityIssuerBinding {
  issueToken(audience: string): Promise<WorkloadIdentityToken>;
}

interface GitHubAppTokenBrokerBinding {
  fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response>;
}

export interface GitHubAppTokenClientBindings {
  readonly WORKLOAD_IDENTITY_ISSUER: WorkloadIdentityIssuerBinding;
  readonly GITHUB_APP_TOKEN_BROKER: GitHubAppTokenBrokerBinding;
}

type UntrustedWorkloadIdentityIssuer = {
  issueToken(audience: string): unknown;
};

