 * Adapts Wrangler's generic generated Service binding to the narrow CWI RPC
 * contract. The separately deployed entrypoint is not available to Wrangler
 * when it generates CyspbotEnv, so the RPC method and its result are checked
 * at this composition boundary.
 */
export function createGitHubAppTokenClientBindings(env: CyspbotEnv): GitHubAppTokenClientBindings {
  return {
    GITHUB_APP_TOKEN_BROKER: env.GITHUB_APP_TOKEN_BROKER,
    WORKLOAD_IDENTITY_ISSUER: requireWorkloadIdentityIssuer(env.WORKLOAD_IDENTITY_ISSUER),
  };
}

/**
 * Requests a GitHub App installation token through the broker's existing OAuth
 * Token Exchange endpoint. The returned Response preserves the broker's OAuth
 * success and error contract for the caller to consume.
 */
