  env: GitHubAppTokenClientBindings,
  request: GitHubAppInstallationTokenRequest,
): Promise<Response> {
  const resource = requireNonEmptyString(request.resource, "resource");
  const scope = requireNonEmptyString(request.scope, "scope");
