import { describe, expect, it } from "vitest";

import { createGitHubRepositoryResource } from "@github-app-token-broker/github/installation-access-token-request";
import type { VerifiedSubjectToken } from "@github-app-token-broker/oidc/id-token-authenticator";
import { parseOidcIssuerIdentifier } from "@github-app-token-broker/oidc/provider-registration";
import { tokenIssuancePolicyPermits } from "@github-app-token-broker/token-issuance-policy";
import {
  cloudflareWorkloadIdentityOidcProviderRegistration,
  oidcProviderRegistrations,
} from "../src/oidc-provider-registrations.ts";
import { tokenIssuancePolicy } from "../src/token-issuance-policy.ts";

const workloadIdentityIssuer = parseOidcIssuerIdentifier("https://workload-identity.chikachow.org");
if (workloadIdentityIssuer === null) {
  throw new TypeError("invalid test OIDC issuer");
}
const otherIssuer = parseOidcIssuerIdentifier("https://other-issuer.example");
if (otherIssuer === null) {
  throw new TypeError("invalid test OIDC issuer");
}
const workloadSubject = "cyspbot";
const cyspbotResource = createGitHubRepositoryResource({
  owner: "chikachow",
  repository: "cyspbot",
});

const exactSubjectToken: VerifiedSubjectToken = {
  claims: {
    aud: "https://cyspbot.chikachow.org",
    exp: 2_000_000_000,
    iat: 1_999_999_000,
    iss: workloadIdentityIssuer,
    jti: "test-jti",
    sub: workloadSubject,
  },
  issuer: workloadIdentityIssuer,
};

const exactRequest = {
  permissions: { contents: "read" },
  resource: cyspbotResource,
  scope: "contents:read",
} as const;

describe("Cloudflare Workload Identity broker composition", () => {
  it("registers the exact issuer as an RS256 generic OIDC profile", () => {
    expect(oidcProviderRegistrations.map((registration) => registration.issuer)).toContain(
      workloadIdentityIssuer,
    );
    expect(cloudflareWorkloadIdentityOidcProviderRegistration).toEqual({
      acceptedIdTokenSigningAlgorithms: ["RS256"],
      idTokenProfile: null,
      issuer: workloadIdentityIssuer,
    });
  });

  it("permits only the exact CWI subject, resource, and contents:read request", () => {
    expect(tokenIssuancePolicyPermits(tokenIssuancePolicy, exactSubjectToken, exactRequest)).toBe(
      true,
    );
  });

  it("denies a different CWI subject", () => {
    const subjectToken: VerifiedSubjectToken = {
      ...exactSubjectToken,
      claims: { ...exactSubjectToken.claims, sub: "urn:chikachow:workload:other" },
    };
    expect(tokenIssuancePolicyPermits(tokenIssuancePolicy, subjectToken, exactRequest)).toBe(false);
  });

  it("denies a different issuer", () => {
    const subjectToken: VerifiedSubjectToken = {
      claims: { ...exactSubjectToken.claims, iss: otherIssuer },
      issuer: otherIssuer,
    };
    expect(tokenIssuancePolicyPermits(tokenIssuancePolicy, subjectToken, exactRequest)).toBe(false);
  });

  it("denies a different repository resource", () => {
    const request = {
      ...exactRequest,
      resource: createGitHubRepositoryResource({
        owner: "chikachow",
        repository: "github-app-token-broker",
      }),
    };
    expect(tokenIssuancePolicyPermits(tokenIssuancePolicy, exactSubjectToken, request)).toBe(false);
  });

  it("denies a stronger contents permission", () => {
    const request = {
      ...exactRequest,
      permissions: { contents: "write" },
      scope: "contents:write",
    } as const;
    expect(tokenIssuancePolicyPermits(tokenIssuancePolicy, exactSubjectToken, request)).toBe(false);
  });

  it("denies an unrelated permission", () => {
    const request = {
      ...exactRequest,
      permissions: { actions: "read" },
      scope: "actions:read",
    } as const;
    expect(tokenIssuancePolicyPermits(tokenIssuancePolicy, exactSubjectToken, request)).toBe(false);
  });
});

